enum class ManualKind { Heading, Para, Bullet, Step }

class ManualBlock(val kind: ManualKind, val text: String)

class ManualSection(val title: String, val summary: String, val blocks: List<ManualBlock>)

object Manual {
    val sections: List<ManualSection> = listOf(
        ManualSection("A first song", "Tracks, scenes, clips, and a first sound.", listOf(
            ManualBlock(ManualKind.Para, "Acidulous is sixteen racks. A rack holds one machine - a synthesizer, a drum machine, a sampler - and that machine is also a track in the song. There is no separate list of instruments and list of parts: the track *is* the instrument."),
            ManualBlock(ManualKind.Heading, "What you are looking at"),
            ManualBlock(ManualKind.Para, "The first screen is the song grid. Track names run down the left, one row each. Scenes run across the top, one column each. Where a row and a column meet there is a clip: the notes that track plays during that scene."),
            ManualBlock(ManualKind.Para, "The bar at the foot of the screen is the same on every screen. Its right-hand end is always the same five controls in the same order - undo, redo, mixer, record and play - so the one you want is where you left it."),
            ManualBlock(ManualKind.Heading, "Making a sound"),
            ManualBlock(ManualKind.Step, "Tap **+ track** and pick a machine. A new song starts with one already."),
            ManualBlock(ManualKind.Step, "Tap the empty clip where your new track meets the first scene. That opens the editor."),
            ManualBlock(ManualKind.Step, "Play the keyboard at the bottom. That is the machine as it stands; tap **patch** at the top of the panel to try the ones it ships with."),
            ManualBlock(ManualKind.Step, "Draw notes in the grid above, or press record and play them in."),
            ManualBlock(ManualKind.Step, "Tap the back arrow to return to the song, and press play."),
            ManualBlock(ManualKind.Heading, "Scenes are sections"),
            ManualBlock(ManualKind.Para, "A scene is a part of the song - an intro, a verse. Every track's clip in that scene plays together, and the scene repeats for as many times as its header says before the song moves to the next one."),
            ManualBlock(ManualKind.Para, "Clips in one scene need not be the same length. A one-bar drum clip under a four-bar chord clip simply repeats four times, which is how most parts are written anyway."),
            ManualBlock(ManualKind.Heading, "Saving"),
            ManualBlock(ManualKind.Para, "The song you are working on is saved continuously and comes back when you next open the app, so nothing is lost by closing it. **save** in the header writes it under its own name; **file** offers a new song, a copy under another name, and the songs you already have."),
        )),
        ManualSection("The song grid", "The arranger, the launcher, and freezing.", listOf(
            ManualBlock(ManualKind.Para, "The grid does two jobs, and the square in its top left corner says which one it is doing."),
            ManualBlock(ManualKind.Heading, "As an arranger"),
            ManualBlock(ManualKind.Para, "This is the default. The song plays scene by scene, left to right: every track plays its clip for that scene, the scene repeats as many times as its header says, and then the next one starts. Press play and it plays the song."),
            ManualBlock(ManualKind.Bullet, "Tap a scene's header to hear that scene on its own."),
            ManualBlock(ManualKind.Bullet, "Hold a scene's header for its menu: settings, insert, duplicate, delete, and move it left or right."),
            ManualBlock(ManualKind.Bullet, "The loop pill at the left of the bottom bar loops the whole song or the scene that is playing."),
            ManualBlock(ManualKind.Heading, "As a launcher"),
            ManualBlock(ManualKind.Para, "Tap the corner square and the same grid becomes a launcher: every track picks its own clip, from any scene, and they need not be from the same one."),
            ManualBlock(ManualKind.Bullet, "Tap a clip to launch it. It starts on the next line rather than immediately, so it arrives in time with what is already playing."),
            ManualBlock(ManualKind.Bullet, "The **q:** pill sets what it waits for. **end** is the musical answer: the clip you are replacing finishes the cycle it is in. Anything else is a plain grid of bars."),
            ManualBlock(ManualKind.Bullet, "Tap a scene's header to launch that whole column at once."),
            ManualBlock(ManualKind.Bullet, "Tap a playing clip to stop it at the end of its cycle; tap the stop control twice to cut everything."),
            ManualBlock(ManualKind.Para, "Every track keeps its own count in this mode, which is the whole point, and the readout above the bottom bar is the only place you can read that as a number."),
            ManualBlock(ManualKind.Heading, "Zooming the grid"),
            ManualBlock(ManualKind.Para, "Two fingers move the grid and change how much of it you can see - drag to move around it, pinch to make the cells larger or smaller. One finger still launches or opens a clip, so nothing is in the way of playing."),
            ManualBlock(ManualKind.Heading, "Clip settings"),
            ManualBlock(ManualKind.Para, "Hold a clip for its settings: how many bars it is, whether it is muted, and the grid it snaps to."),
            ManualBlock(ManualKind.Heading, "What a cell tells you"),
            ManualBlock(ManualKind.Para, "The number of bars is in the corner, with **1** for a one-shot and **M** for a muted clip. A cell on an audio track also shows its waveform and how many of its four lanes hold a recording - and says so **in amber** when one of them was recorded at a tempo this scene does not play at, since audio does not stretch."),
            ManualBlock(ManualKind.Heading, "Freezing"),
            ManualBlock(ManualKind.Para, "Freezing renders a clip to audio and plays that instead of the machine, which gives the processor back to everything else. Freeze one clip, a whole scene or a whole track from the menus."),
            ManualBlock(ManualKind.Para, "A freeze is tied to the tempo it was made at. Change the tempo and the frozen clips say so, and can be thawed or re-frozen."),
        )),
        ManualSection("The editor", "Drawing notes, and what one note decides.", listOf(
            ManualBlock(ManualKind.Para, "Opening a clip gives you the grid at the top, the machine's own controls in the middle, and the instrument at the bottom."),
            ManualBlock(ManualKind.Heading, "The grid"),
            ManualBlock(ManualKind.Para, "For a melodic machine it is a piano roll: pitch up the side, time across."),
            ManualBlock(ManualKind.Bullet, "Tap an empty square to put a note there; tap a note to take it away."),
            ManualBlock(ManualKind.Bullet, "Drag a note to move it, or drag its right-hand edge to make it longer."),
            ManualBlock(ManualKind.Bullet, "**Two fingers move the view**: drag to scroll through pitch and time, pinch to zoom. One finger always draws, which is what keeps the two apart."),
            ManualBlock(ManualKind.Bullet, "The **scl** corner cycles how the scale is shown: every note, the scale's notes lit, or only the scale's notes."),
            ManualBlock(ManualKind.Para, "For a drum machine it is a grid of steps instead, one row per voice, and a tap puts a hit in."),
            ManualBlock(ManualKind.Heading, "Playing it in"),
            ManualBlock(ManualKind.Para, "Press record and play. What you play is written into the clip, quantised to the clip's grid. The count-in, if you have set one, is in the settings."),
            ManualBlock(ManualKind.Para, "The keyboard reads **where** you hit a key: low on the key is soft, high is hard. The pill in the bottom bar switches that off, so every note comes out at full strength - which is what you want when you are tapping a part in rather than playing it. The drum pads work the same way and have their own setting."),
            ManualBlock(ManualKind.Para, "Drag the performance row - the strip of controls just above the keys - up or down to make the instrument taller or shorter."),
            ManualBlock(ManualKind.Heading, "What a note can decide"),
            ManualBlock(ManualKind.Para, "Below the grid is a lane, folded away until you want it. Open it and pick what it is showing; then drag inside it to set that property on each note."),
            ManualBlock(ManualKind.Bullet, "**note volume** - how hard that note is played."),
            ManualBlock(ManualKind.Bullet, "**probability** - how often it plays at all. A note at 50 plays half the time."),
            ManualBlock(ManualKind.Bullet, "**trig condition** - when it is allowed to play. `1:4` plays on the first of every four passes; `pre` plays only if the last conditional note played, `!pr` only if it did not; `fil` plays only while fill is held, `!fi` only while it is not."),
            ManualBlock(ManualKind.Bullet, "**ratchet** - how many times it retriggers within its own step."),
            ManualBlock(ManualKind.Bullet, "**micro timing** - how far off the grid it sits, up to half a sixteenth either way."),
            ManualBlock(ManualKind.Para, "The same seed drives every one of these, so a clip that varies still plays the same bar twice when you want it to."),
            ManualBlock(ManualKind.Heading, "Automation"),
            ManualBlock(ManualKind.Para, "The strip under the note lane records and draws a parameter over time. Move any knob while recording and the move is written there; afterwards, pick the parameter and draw it by hand."),
            ManualBlock(ManualKind.Heading, "Folding"),
            ManualBlock(ManualKind.Para, "The lanes, the machine panel and the instrument each fold away with the small chevron at their edge, and the grid takes the height. On a phone that is the difference between four rows of pitch and fourteen."),
        )),
        ManualSection("The machines", "Nineteen instruments, a four-track for your recordings, and what each is for.", listOf(
            ManualBlock(ManualKind.Para, "Every machine here was written for this app. None is sampled from anything else, and none is a copy of anything: they stand in familiar places and are their own designs. Tap a rack's machine name to change it."),
            ManualBlock(ManualKind.Heading, "Bass and lead"),
            ManualBlock(ManualKind.Bullet, "**Subvert** - the signature bass mono. Accent is velocity and slide is legato, so a line is played rather than programmed: hold one note into the next to slide, hit it hard to accent."),
            ManualBlock(ManualKind.Bullet, "**Trinity** - three oscillators with wavetables, density and drift, two filters, six envelopes, three LFOs and a twelve-slot modulation matrix. The general-purpose poly."),
            ManualBlock(ManualKind.Bullet, "**Ratio** - six-operator FM. Two algorithms with a morph between them, so the routing itself is something you can sweep, and ratios you can snap to whole numbers or skew off them."),
            ManualBlock(ManualKind.Heading, "Keys and air"),
            ManualBlock(ManualKind.Bullet, "**Manual** - an organ. Two manuals and pedals over one shared generator, four models and a rotary cabinet. The keys tap a shared set of wheels, which is why its polyphony costs nothing and why it sounds like an organ."),
            ManualBlock(ManualKind.Bullet, "**Cumulus** - pads built as a spectrum rather than as oscillators: bands of partials, four frames morphed between, stretch, vowels and drift."),
            ManualBlock(ManualKind.Bullet, "**Mosaic** - the multisample player. Key and velocity zones, crossfades, a layer scan, and a grain engine over the whole map."),
            ManualBlock(ManualKind.Heading, "Modelled instruments"),
            ManualBlock(ManualKind.Para, "These are solved rather than sampled, so they respond to how you play them."),
            ManualBlock(ManualKind.Bullet, "**Filament** - strings. Six ways to excite them, including the audio input, plus a sympathetic bank, stiffness, tension and preparation."),
            ManualBlock(ManualKind.Bullet, "**Brazen** - brass, tuba to trumpet. Lips blown open against a tube, and a section whose players listen to each other."),
            ManualBlock(ManualKind.Bullet, "**Timber** - woodwinds. Reed, double reed and air jet, cylinder and cone, and a tube that goes on below the note you fingered."),
            ManualBlock(ManualKind.Bullet, "**Resonance** - modal percussion. Eight objects struck somewhere with something, ringing into each other."),
            ManualBlock(ManualKind.Heading, "Drums"),
            ManualBlock(ManualKind.Bullet, "**Hexbeat** - a drum synthesizer in the small-box vocabulary, grown to the kit those boxes never had. Thirteen voices, nothing sampled."),
            ManualBlock(ManualKind.Bullet, "**Genesis** - the big drum box: a swept kick, six-square metal, circuit drift, and a bus compressor with the kick wired to its side chain."),
            ManualBlock(ManualKind.Bullet, "**Forage** - the sample drum machine. Thirteen pads, your own files, with a filter, a crusher and a pitch envelope on each."),
            ManualBlock(ManualKind.Heading, "Sound as material"),
            ManualBlock(ManualKind.Bullet, "**Pollen** - granular, over a file you mount or the sound coming in live."),
            ManualBlock(ManualKind.Bullet, "**Dice** - a slicer. A loop cut into pieces, with a probability on every trigger, and a hold that makes a roll repeatable."),
            ManualBlock(ManualKind.Bullet, "**Cipher** - a vocoder, where the map between the analysis bands and the synthesis bands is the instrument: remap it, freeze it, smear it, swap it."),
            ManualBlock(ManualKind.Bullet, "**Molt** - a voice you write for. Sing a take in and the piano roll tunes it: draw the line, sing anything, and the take is pulled onto the notes."),
            ManualBlock(ManualKind.Heading, "Anything else"),
            ManualBlock(ManualKind.Bullet, "**Formulate** - an 8-bit machine with tracker tables and a small expression language, so a waveform is something you write rather than something you pick."),
            ManualBlock(ManualKind.Bullet, "**Nexus** - a modular whose blocks are this app's own instruments and whose patch is text you can read."),
            ManualBlock(ManualKind.Heading, "Audio"),
            ManualBlock(ManualKind.Bullet, "**Bias** - a four-track that runs along the song. Where every other machine plays the notes in a cell, Bias plays the *recording* in a cell: four lanes, and they sound together, so choosing between three takes is muting two of them and doubling a vocal is unmuting a second. **audio…** on a lane puts a recording there, and it belongs to that cell - a take that crosses four scenes is four cells naming the same file, so no second timeline exists and scenes of different lengths need nothing said about them. The level and the mute on each lane are ordinary parameters, which is the whole reason they are there rather than on the recording: they automate in the strip under the grid, they map to a pad or a knob, and they record while you play. A muted section is a mute drawn in that cell. Recording onto it is in [Recording and samples](08-recording-and-samples.md): arm a lane, press record, press play, and what you sing is cut at the scene lines when you stop. Opening a Bias cell gives you the lanes themselves, along this cell's whole cycle - both passes of a scene set to repeat, because that is what a four-track plays. Drag a lane's body to move where it comes in; drag either end to trim the recording without moving it; tap the number at the left to mute the lane. An empty lane is a tap away from the library. Audio does not stretch. A take enters on the bar wherever it is put, and runs at the speed it was recorded at; when that is not the tempo the scene plays at, the lane says so in amber. **Its patches are recording media.** Bias is the signal a tape machine mixes into its record head, and setting it is how you choose between a clean transfer and a compressed, rolled-off one - so a patch here is a cassette, a fifteen-ips reel, a Portastudio, a MiniDisc, a telephone line, a wax cylinder. They colour what comes out and **never the recordings**, so trying one costs nothing and undoes itself; **Init** is the default and plays the file back untouched. A patch carries the medium only, so trying a different tape does not disturb your four lane levels."),
            ManualBlock(ManualKind.Heading, "Patches"),
            ManualBlock(ManualKind.Para, "Every machine ships with patches, shelved by family. **patch** at the top of the panel opens the browser; your own saved patches get a tab of their own and are the only ones you can delete."),
        )),
        ManualSection("Effects and mixing", "Two inserts a track, two sends, a master.", listOf(
            ManualBlock(ManualKind.Heading, "Inserts"),
            ManualBlock(ManualKind.Para, "Each track has two insert slots. **fx** in the editor's bottom bar swaps the panel under the grid for them."),
            ManualBlock(ManualKind.Para, "Fourteen effects: delay, reverb, equaliser, distortion, compressor, filter, bitcrusher, phaser, flanger, chorus, tremolo, width, pitch shifter and harmonizer. Each has the controls you expect **and one more that you do not** - the extra is marked in the accent colour, so the familiar set stays recognisable and the addition is never a surprise."),
            ManualBlock(ManualKind.Para, "A slot can be bypassed without being emptied, which is the difference between comparing and deleting."),
            ManualBlock(ManualKind.Heading, "The mixer"),
            ManualBlock(ManualKind.Para, "The mixer pill opens the strips: one per track and one master."),
            ManualBlock(ManualKind.Bullet, "**Fader and meter** per track, with mute and solo."),
            ManualBlock(ManualKind.Bullet, "**Two sends**, to two effects shared by the whole song. Sends are how several tracks sit in one room without each paying for its own."),
            ManualBlock(ManualKind.Bullet, "**Pan**, and a MIDI row for what this track sends out."),
            ManualBlock(ManualKind.Bullet, "**The master** carries the limiter, and the meter that tells you whether you are asking it for too much."),
            ManualBlock(ManualKind.Heading, "The two sends"),
            ManualBlock(ManualKind.Para, "They start as a reverb and a delay, which is what a send is usually for, but either can hold **any of the fourteen effects**. The two chips in the master strip say what is on them: tap one to switch it off and on, hold it to choose the effect and set it up. Every channel's two send sliders take their names from the same place, so a strip says what it is sending to."),
            ManualBlock(ManualKind.Para, "A send is fully wet, always. What comes back is the effect and nothing else, because the dry sound is already in the mix on its own channel - so there is no wet/dry control in a send, and that is the one thing its editor does not offer that an insert's does."),
            ManualBlock(ManualKind.Para, "Some things are worth more on a send than in a track's own slot: a pitch shifter fed a little from several tracks is a chorus of octaves nobody is playing, and a bitcrusher on a send is a second, ruined copy of the mix sitting behind it."),
            ManualBlock(ManualKind.Heading, "Tempo, signature and the click"),
            ManualBlock(ManualKind.Para, "The tempo is in the song header. Tapping it opens the signature and the metronome: which sound the click makes, what it counts, how loud it is, whether it plays always or only while recording, and how many bars to count in before recording starts."),
        )),
        ManualSection("Scale, chord and arpeggio", "What a note becomes on its way out.", listOf(
            ManualBlock(ManualKind.Para, "Every track has three of these, and they sit in the row just above the keyboard. **A tap says whether one is running; holding it open lets you choose.** They are the same gesture as every other slot in the app."),
            ManualBlock(ManualKind.Para, "They act on what you *play* and on what the clip plays back, which is why a part recorded with an arpeggio on it is written down as the notes you held, not the notes you heard. Switch the arpeggio off and the part is a chord again."),
            ManualBlock(ManualKind.Heading, "Scale"),
            ManualBlock(ManualKind.Para, "Thirty-three scales, each with a key. With one running, the keyboard collapses to only the notes the scale allows, so a phone's worth of width goes further and a wrong note is not available to play."),
            ManualBlock(ManualKind.Para, "The piano roll can show the scale three ways - every note, the scale's notes lit, or only the scale's notes - from the **scl** corner."),
            ManualBlock(ManualKind.Heading, "Chord"),
            ManualBlock(ManualKind.Para, "Plays a chord from every note you play. Either a fixed shape that follows your finger, or the chord the running scale builds on that degree, so the harmony stays in key as the line moves."),
            ManualBlock(ManualKind.Heading, "Arpeggio"),
            ManualBlock(ManualKind.Para, "Takes the notes you are holding and plays them one at a time: the order, the rate, how many octaves it climbs, how long each note lasts, and a chance that any given step is skipped."),
        )),
        ManualSection("MIDI and playing with others", "Keyboards, clock, MPE and Link.", listOf(
            ManualBlock(ManualKind.Para, "**MIDI…** in the file menu is where all of this lives, in the order somebody asks the questions: what is coming in, where it goes, and what goes out."),
            ManualBlock(ManualKind.Heading, "Playing the app from a keyboard"),
            ManualBlock(ManualKind.Para, "USB and Bluetooth keyboards are handled by the app itself. Arriving notes go either to whichever track is open - so changing track changes what you are playing - or to a track you pin, so it stays put whatever you are looking at."),
            ManualBlock(ManualKind.Para, "**Per-note expression** is understood where a machine can use it. A controller that bends one finger without bending the others will bend one note without bending the others, on the machines that have somewhere to put it, and the zone and bend range are set here. It is recorded as well as played: a note remembers its own bend, pressure and slide."),
            ManualBlock(ManualKind.Heading, "Mapping a controller"),
            ManualBlock(ManualKind.Para, "Long-press redo to enter mapping mode. Every control that can be mapped says so, and tapping one arms it: move a knob or press a key on your controller and the two are joined. Knobs, faders, mixer controls and transport buttons can all be mapped, to a CC **or** to a note."),
            ManualBlock(ManualKind.Para, "A mapped parameter records into the automation lane for free, because it moves down the same path your finger does. A mapped action - play, stop, fill - never records, because a button press is not a value."),
            ManualBlock(ManualKind.Heading, "Clock"),
            ManualBlock(ManualKind.Para, "The app can send MIDI clock to hardware, with start, stop and song position, and it can follow somebody else's. Following means the tempo control goes quiet: the tempo is theirs."),
            ManualBlock(ManualKind.Para, "What goes out is set per track: notes, or clock, or both."),
            ManualBlock(ManualKind.Heading, "Link"),
            ManualBlock(ManualKind.Para, "Link shares tempo and the position within the bar with any other Link app on the same network, in both directions. Switch it on and the peer count appears. It carries the beat and the bar, not the song position - so everybody agrees on where the downbeat is without anybody being in charge."),
        )),
        ManualSection("Recording and samples", "Getting audio in, and what to do with it.", listOf(
            ManualBlock(ManualKind.Heading, "The recording window"),
            ManualBlock(ManualKind.Para, "One window does all of it, and it opens wherever audio is wanted - a pad on the sample machine, a loop for the slicer, a buffer for the granular, a take to sing into the voice machine."),
            ManualBlock(ManualKind.Bullet, "**Record** - choose which input, watch the level, and capture."),
            ManualBlock(ManualKind.Bullet, "**Edit** - trim the ends, set the level, and take the rumble off the bottom with a low cut."),
            ManualBlock(ManualKind.Bullet, "**Library** - everything you have recorded or imported, to use again."),
            ManualBlock(ManualKind.Para, "What it hands back is a file, so the same recording can be used by more than one machine."),
            ManualBlock(ManualKind.Heading, "Importing"),
            ManualBlock(ManualKind.Para, "Bring in WAV, AIFF, FLAC and MP3. Whatever the format, it is decoded once on the way in and stored as a WAV, so nothing downstream has to know about formats and a song load is never a decode."),
            ManualBlock(ManualKind.Heading, "Recording onto a track"),
            ManualBlock(ManualKind.Para, "**Bias** is the four-track, and recording onto it is how a song gets a voice on it. Open a Bias cell, tap the red dot beside the lane you want, arm the transport's record button, and press play: what you sing is written while the song plays under you, and the other lanes keep playing, which is what overdubbing on a four-track is."),
            ManualBlock(ManualKind.Para, "**The take is cut at the scene lines when you disarm.** One recording sung over a whole song becomes one cell per scene, each a window into the same file - so nothing is copied, and every scene you crossed now holds the part of the take that belongs to it. Scenes the track had nothing in are made as they are reached."),
            ManualBlock(ManualKind.Para, "The whole recording stays in the sound library under its own name, so a split you did not want can be thrown away and the audio placed by hand instead."),
            ManualBlock(ManualKind.Para, "One lane records at a time, because there is one recorder. Arming a second lane lets the first one go."),
            ManualBlock(ManualKind.Para, "Two things it will tell you rather than guess at. If the recorder fell behind and the take has a gap in it, it is **not** split - every moment after the gap would be in the wrong place - and it is left in the library whole. And if the transport never played, nothing was recorded against a scene and it says so."),
            ManualBlock(ManualKind.Heading, "The machines that take audio"),
            ManualBlock(ManualKind.Bullet, "**Forage** - a pad each, with a filter, a crusher and a pitch envelope."),
            ManualBlock(ManualKind.Bullet, "**Mosaic** - a map of zones across the keyboard and across velocity, from your own files or a SoundFont."),
            ManualBlock(ManualKind.Bullet, "**Pollen** - grains over the file, or over what is coming in live."),
            ManualBlock(ManualKind.Bullet, "**Dice** - the loop cut into slices you can roll."),
            ManualBlock(ManualKind.Bullet, "**Molt** - a sung take, retuned by the piano roll."),
            ManualBlock(ManualKind.Bullet, "**Cipher** and **Filament** can both take the live input as their source."),
            ManualBlock(ManualKind.Bullet, "**Bias** - four lanes of recordings, along the length of the song. Unlike the rest of these, its material belongs to the cells rather than to the machine; see [The machines](04-the-machines.md)."),
        )),
        ManualSection("Exporting", "Getting the song out.", listOf(
            ManualBlock(ManualKind.Para, "**Export…** in the file menu renders the song faster than real time, through the same engine that plays it - so what you export is what you heard, including the tail after the last note."),
            ManualBlock(ManualKind.Heading, "Formats"),
            ManualBlock(ManualKind.Bullet, "**WAV** and **AIFF** - uncompressed, at 16 or 24 bits."),
            ManualBlock(ManualKind.Bullet, "**FLAC** - the same samples, smaller."),
            ManualBlock(ManualKind.Bullet, "**MP3** - at the bitrate you choose."),
            ManualBlock(ManualKind.Para, "The depth row becomes a rate row for the lossy formats, because a bitrate is what that question means there."),
            ManualBlock(ManualKind.Heading, "Stems"),
            ManualBlock(ManualKind.Para, "Export stems and every track is written as its own file, in one pass, with the mix left alone. That is a mixing session somewhere else, without re-recording anything."),
            ManualBlock(ManualKind.Heading, "Two renders of the same song match"),
            ManualBlock(ManualKind.Para, "Exporting the same song twice gives two identical files, because every machine is put back to where it started before the render begins. If you are comparing two exports and they differ, something in between changed."),
        )),
        ManualSection("Settings", "What follows you rather than the song.", listOf(
            ManualBlock(ManualKind.Para, "Nothing in this window is saved into a song. These are statements about you, your eyes and this particular phone, so opening somebody else's song never changes how your app behaves."),
            ManualBlock(ManualKind.Heading, "display"),
            ManualBlock(ManualKind.Bullet, "**theme** - dark, light, or whatever the phone is doing."),
            ManualBlock(ManualKind.Bullet, "**interface size** - makes everything larger, for a dense screen or for eyes that want it. Four steps; the app lays itself out again as you tap."),
            ManualBlock(ManualKind.Bullet, "**screen while playing** - whether the screen is allowed to sleep."),
            ManualBlock(ManualKind.Heading, "audio"),
            ManualBlock(ManualKind.Bullet, "**audio buffer** - tight, balanced or safe. Tight is the lowest latency the device will give and will crackle on a phone that cannot keep up; safe buys a phone that cannot the room to finish late. The line under it is live: frames, milliseconds and how many times it has dropped out."),
            ManualBlock(ManualKind.Bullet, "**machine voice limit** - how many notes a track may hold at once. The oldest goes first."),
            ManualBlock(ManualKind.Bullet, "**effect quality** - full is everything; lean trades reverb density and distortion oversampling for processor."),
            ManualBlock(ManualKind.Heading, "record"),
